// 接收並驗證傳入數據
const body = $json.body || $json;
const data = body.data || body;
const collection = body.collection || 'knowledge_base';
const source = body.source || 'unknown';

// 標準化數據格式
if (Array.isArray(data)) {
  return data.map(item => ({
    json: {
      ...item,
      _collection: collection,
      _source: source,
      _processed_at: new Date().toISOString()
    }
  }));
} else {
  return [{
    json: {
      ...data,
      _collection: collection,
      _source: source,
      _processed_at: new Date().toISOString()
    }
  }];
}

// 將結構化數據轉換為可向量化的文本
const item = $json;
const collection = item._collection;

// 根據collection類型決定文本生成策略
let vectorText = '';
let pointId = '';

switch(collection) {
  case 'customer_data':
    vectorText = [
      `客戶資料：${item.name || ''}`,
      `需求：${item.requirements || item.interest || ''}`,
      `預算：${item.budget || ''}`,
      `時間：${item.timeline || ''}`,
      `來源：${item.source || ''}`,
      `備註：${item.notes || ''}`
    ].filter(Boolean).join('\n');
    pointId = item.form_response_id || item.id || Date.now().toString();
    break;

  case 'sales_insights':
    vectorText = [
      `銷售洞察：${item.title || ''}`,
      `內容：${item.content || ''}`,
      `來源：${item.source || ''}`,
      `日期：${item.date || ''}`
    ].filter(Boolean).join('\n');
    pointId = item.id || Date.now().toString();
    break;

  default: // knowledge_base
    vectorText = [
      `標題：${item.title || ''}`,
      `內容：${item.content || item.description || ''}`,
      `分類：${item.category || ''}`,
      `來源：${item._source || ''}`,
      `標籤：${Array.isArray(item.tags) ? item.tags.join(', ') : (item.tags || '')}`
    ].filter(Boolean).join('\n');
    pointId = item.id || Buffer.from(item.url || item.title || '').toString('base64').substring(0, 20);
}

return [{
  json: {
    ...item,
    _vector_text: vectorText,
    _point_id: pointId.replace(/[^a-zA-Z0-9-]/g, '_').substring(0, 36)
  }
}];
